(async () => {
  const res = await fetch('https://www.zhihu.com/api/v3/feed/topstory/hot-lists/total?limit=50', {
    credentials: 'include'
  });
  const text = await res.text();
  const d = JSON.parse(
    text.replace(/("id"\s*:\s*)(\d{16,})/g, '$1"$2"')
  );
  return (d?.data || []).map((item) => {
    const t = item.target || {};
    const questionId = t.id == null ? '' : String(t.id);
    return {
      title: t.title,
      url: 'https://www.zhihu.com/question/' + questionId,
      answer_count: t.answer_count,
      follower_count: t.follower_count,
      heat: item.detail_text || '',
    };
  });
})()

async () => {
  const results = [];
  const limit = ${{ args.limit }};

  const parsePage = (doc) => {
    const items = doc.querySelectorAll('.item');
    for (const item of items) {
      if (results.length >= limit) break;

      const rankEl = item.querySelector('.pic em');
      const linkEl = item.querySelector('a');
      const titleEl = item.querySelector('.title');
      const ratingEl = item.querySelector('.rating_num');

      const href = linkEl?.href || '';
      const matchResult = href.match(/subject\/(\d+)/);
      const id = matchResult ? matchResult[1] : '';

      const title = titleEl?.textContent?.trim() || '';
      const rank = parseInt(rankEl?.textContent || '0', 10);
      const rating = ratingEl?.textContent?.trim() || '';

      if (id && title) {
        results.push({
          rank: rank || results.length + 1,
          id,
          title,
          rating: rating ? parseFloat(rating) : 0,
          url: href
        });
      }
    }
  };

  parsePage(document);

  for (let start = 25; start < 250 && results.length < limit; start += 25) {
    const resp = await fetch(`https://movie.douban.com/top250?start=${start}`);
    if (!resp.ok) break;
    const html = await resp.text();
    if (!html) break;

    const doc = new DOMParser().parseFromString(html, 'text/html');
    parsePage(doc);
    await new Promise(r => setTimeout(r, 150));
  }

  return results;
}
